cssCode:
.kinetic-wrap { display: flex; gap: 5px; cursor: pointer; }
.kinetic-letter {
  font-size: 50px; font-weight: 900; font-family: sans-serif; color: #ff007f;
  text-transform: uppercase; transition: transform 0.5s cubic-bezier(0.175, 0.885, 0.32, 1.275), color 0.3s;
}
.kinetic-wrap:hover .kinetic-letter {
  transform: translateY(-20px) scale(1.1); color: #00ffcc; text-shadow: 0 10px 20px rgba(0,255,204,0.5);
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'kinetic-wrap';

const word = 'KINETIC';
word.split('').forEach((letter, index) => {
  const span = document.createElement('span');
  span.className = 'kinetic-letter';
  span.innerText = letter;
  span.style.transitionDelay = `${index * 0.05}s`;
  wrap.appendChild(span);
});
c.appendChild(wrap);
